import { useState, useEffect } from 'react'
import Navbar from './components/Navbar'
import Footer from './components/Footer'
import HomePage from './pages/HomePage'
import ChartPage from './pages/ChartPage'
import IdeasPage from './pages/IdeasPage'
import MarketsPage from './pages/MarketsPage'
import BrokersPage from './pages/BrokersPage'

type Page = 'home' | 'chart' | 'ideas' | 'markets' | 'brokers'

function getPageFromHash(): Page {
  const hash = window.location.hash.replace('#', '')
  const validPages: Page[] = ['home', 'chart', 'ideas', 'markets', 'brokers']
  return validPages.includes(hash as Page) ? (hash as Page) : 'home'
}

export default function App() {
  const [page, setPage] = useState<Page>(getPageFromHash)

  useEffect(() => {
    const handleHash = () => setPage(getPageFromHash())
    window.addEventListener('hashchange', handleHash)
    return () => window.removeEventListener('hashchange', handleHash)
  }, [])

  const navigate = (p: Page) => {
    window.location.hash = p
    setPage(p)
    window.scrollTo(0, 0)
  }

  const renderPage = () => {
    switch (page) {
      case 'chart': return <ChartPage />
      case 'ideas': return <IdeasPage />
      case 'markets': return <MarketsPage />
      case 'brokers': return <BrokersPage />
      default: return <HomePage navigate={navigate} />
    }
  }

  return (
    <div className="grain min-h-screen flex flex-col">
      <Navbar currentPage={page} navigate={navigate} />
      <main className="flex-1">
        {renderPage()}
      </main>
      <Footer navigate={navigate} />
    </div>
  )
}

