import { useState } from 'react'
import { siteConfig } from '../config/site'

interface NavbarProps {
  currentPage: string
  navigate: (page: 'home' | 'chart' | 'ideas' | 'markets' | 'brokers') => void
}

export default function Navbar({ currentPage, navigate }: NavbarProps) {
  const [mobileOpen, setMobileOpen] = useState(false)

  const navItems = [
    { label: 'Products', page: 'chart' as const },
    { label: 'Community', page: 'ideas' as const },
    { label: 'Markets', page: 'markets' as const },
    { label: 'Brokers', page: 'brokers' as const },
  ]

  return (
    <nav className="sticky top-0 z-50 border-b border-border bg-bg-primary/95 backdrop-blur-md">
      <div className="max-w-[1440px] mx-auto px-4 sm:px-6 h-14 flex items-center justify-between">
        <div className="flex items-center gap-8">
          <button onClick={() => navigate('home')} className="flex items-center gap-2 hover:opacity-80 transition-opacity">
            <div className="w-8 h-8 rounded-lg bg-accent flex items-center justify-center">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
              </svg>
            </div>
            <span className="font-display font-bold text-lg text-white tracking-tight">
              {siteConfig.name}
            </span>
          </button>

          <div className="hidden lg:flex items-center gap-1">
            {navItems.map(item => (
              <button
                key={item.page}
                onClick={() => navigate(item.page)}
                className={`px-3 py-1.5 rounded-md text-sm font-medium transition-colors ${
                  currentPage === item.page
                    ? 'text-accent bg-accent/10'
                    : 'text-text-secondary hover:text-text-primary hover:bg-bg-hover'
                }`}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-3">
          <div className="hidden md:flex items-center bg-bg-secondary rounded-md px-3 py-1.5 border border-border">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-text-muted mr-2">
              <circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" />
            </svg>
            <input
              type="text"
              placeholder="Search"
              className="bg-transparent text-sm text-text-primary placeholder-text-muted outline-none w-32 lg:w-48"
            />
            <kbd className="hidden lg:inline text-xs text-text-muted bg-bg-primary px-1.5 py-0.5 rounded border border-border ml-2">/</kbd>
          </div>

          <button className="hidden sm:block text-sm text-text-secondary hover:text-text-primary transition-colors px-3 py-1.5">
            Log in
          </button>
          <button className="bg-accent hover:bg-accent-hover text-white text-sm font-semibold px-4 py-1.5 rounded-md transition-colors">
            Get started
          </button>

          <button
            onClick={() => setMobileOpen(!mobileOpen)}
            className="lg:hidden p-1.5 text-text-secondary hover:text-text-primary"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              {mobileOpen ? (
                <path d="M18 6 6 18M6 6l12 12" />
              ) : (
                <><line x1="4" x2="20" y1="6" y2="6" /><line x1="4" x2="20" y1="12" y2="12" /><line x1="4" x2="20" y1="18" y2="18" /></>
              )}
            </svg>
          </button>
        </div>
      </div>

      {mobileOpen && (
        <div className="lg:hidden border-t border-border bg-bg-primary px-4 py-3 space-y-1">
          {navItems.map(item => (
            <button
              key={item.page}
              onClick={() => { navigate(item.page); setMobileOpen(false) }}
              className={`block w-full text-left px-3 py-2 rounded-md text-sm font-medium transition-colors ${
                currentPage === item.page
                  ? 'text-accent bg-accent/10'
                  : 'text-text-secondary hover:text-text-primary hover:bg-bg-hover'
              }`}
            >
              {item.label}
            </button>
          ))}
        </div>
      )}
    </nav>
  )
}

