interface SparklineProps {
  positive: boolean
  width?: number
  height?: number
}

export default function Sparkline({ positive, width = 80, height = 28 }: SparklineProps) {
  const points = positive
    ? [0, 20, 10, 18, 20, 14, 30, 16, 40, 10, 50, 12, 60, 6, 70, 8, 80, 4]
    : [0, 4, 10, 8, 20, 6, 30, 12, 40, 10, 50, 16, 60, 14, 70, 18, 80, 22]

  const pathD = points.reduce((d, val, i) => {
    if (i % 2 === 0) {
      const x = (val / 80) * width
      const y = points[i + 1] !== undefined ? (points[i + 1] / 28) * height : 0
      return d + (i === 0 ? `M ${x} ${y}` : ` L ${x} ${y}`)
    }
    return d
  }, '')

  const color = positive ? '#26a69a' : '#F7525F'

  return (
    <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} className="flex-shrink-0">
      <path d={pathD} fill="none" stroke={color} strokeWidth="1.5" />
    </svg>
  )
}

