import { useState, useMemo } from 'react'
import { siteConfig } from '../config/site'

type TimeFrame = '1D' | '5D' | '1M' | '3M' | '6M' | 'YTD' | '1Y' | '5Y' | 'All'
type FinTab = 'Annual' | 'Quarterly'

function CandlestickChart({ timeframe }: { timeframe: TimeFrame }) {
  const candles = useMemo(() => {
    const seed = timeframe.charCodeAt(0)
    const count = timeframe === '1D' ? 24 : timeframe === '5D' ? 35 : timeframe === '1M' ? 22 : 40
    const basePrice = 263
    return Array.from({ length: count }, (_, i) => {
      const rand = Math.sin(seed * 100 + i * 7.3) * 0.5 + 0.5
      const trend = i / count * (seed % 2 === 0 ? 3 : -2)
      const open = basePrice + trend + (rand - 0.5) * 8
      const close = open + (Math.sin(seed + i * 3.7) > 0 ? 1 : -1) * (rand * 4 + 0.5)
      const high = Math.max(open, close) + rand * 2
      const low = Math.min(open, close) - rand * 2
      return { open, close, high, low, positive: close >= open }
    })
  }, [timeframe])

  const allPrices = candles.flatMap(c => [c.high, c.low])
  const minP = Math.min(...allPrices) - 2
  const maxP = Math.max(...allPrices) + 2
  const chartW = 800
  const chartH = 400
  const padX = 60
  const padY = 20
  const drawW = chartW - padX * 2
  const drawH = chartH - padY * 2

  const toY = (p: number) => padY + drawH - ((p - minP) / (maxP - minP)) * drawH
  const barW = Math.max(2, (drawW / candles.length) * 0.6)
  const gap = drawW / candles.length

  const gridLines = 5

  return (
    <svg viewBox={`0 0 ${chartW} ${chartH}`} className="w-full h-full" preserveAspectRatio="xMidYMid meet">
      <defs>
        <linearGradient id="bgGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#131722" />
          <stop offset="100%" stopColor="#0F0F0F" />
        </linearGradient>
      </defs>
      <rect width={chartW} height={chartH} fill="url(#bgGrad)" rx="0" />

      {Array.from({ length: gridLines + 1 }, (_, i) => {
        const y = padY + (drawH / gridLines) * i
        const price = maxP - ((maxP - minP) / gridLines) * i
        return (
          <g key={i}>
            <line x1={padX} y1={y} x2={chartW - padX} y2={y} stroke="#2a2e39" strokeWidth="0.5" />
            <text x={padX - 8} y={y + 4} textAnchor="end" fill="#787b86" fontSize="10" fontFamily="JetBrains Mono, monospace">
              {price.toFixed(2)}
            </text>
          </g>
        )
      })}

      {candles.map((c, i) => {
        const x = padX + gap * i + gap / 2
        return (
          <g key={i}>
            <line x1={x} y1={toY(c.high)} x2={x} y2={toY(c.low)} stroke={c.positive ? '#26a69a' : '#F7525F'} strokeWidth="1" />
            <rect
              x={x - barW / 2}
              y={toY(Math.max(c.open, c.close))}
              width={barW}
              height={Math.max(1, Math.abs(toY(c.open) - toY(c.close)))}
              fill={c.positive ? '#26a69a' : '#F7525F'}
              rx="0.5"
            />
          </g>
        )
      })}

      <text x={padX} y={padY - 5} fill="#d1d4dc" fontSize="13" fontFamily="Space Grotesk, sans-serif" fontWeight="600">
        AAPL — Apple Inc
      </text>
      <text x={padX} y={padY + 14} fill="#F7525F" fontSize="11" fontFamily="JetBrains Mono, monospace">
        263.40  −3.03 (−1.14%)
      </text>
    </svg>
  )
}

export default function ChartPage() {
  const [timeframe, setTimeframe] = useState<TimeFrame>('1M')
  const [expandedCategories, setExpandedCategories] = useState<Record<string, boolean>>({
    Indices: true, Stocks: true, Futures: true, Forex: false, Crypto: false,
  })
  const [finTab, setFinTab] = useState<FinTab>('Annual')
  const [selectedSymbol, setSelectedSymbol] = useState('AAPL')

  const timeframes: TimeFrame[] = ['1D', '5D', '1M', '3M', '6M', 'YTD', '1Y', '5Y', 'All']
  const categories = Object.keys(siteConfig.watchlist) as (keyof typeof siteConfig.watchlist)[]
  const detail = siteConfig.stockDetail
  const fin = siteConfig.financials

  const toggleCategory = (cat: string) => {
    setExpandedCategories(prev => ({ ...prev, [cat]: !prev[cat] }))
  }

  return (
    <div className="h-[calc(100vh-3.5rem)] flex flex-col lg:flex-row overflow-hidden">
      {/* Watchlist Sidebar */}
      <div className="w-full lg:w-60 xl:w-72 border-b lg:border-b-0 lg:border-r border-border bg-bg-secondary flex-shrink-0 overflow-y-auto max-h-48 lg:max-h-none">
        <div className="p-3 border-b border-border flex items-center justify-between">
          <h3 className="font-display font-semibold text-sm text-white">Watchlist</h3>
          <button className="text-text-muted hover:text-text-primary p-1">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="12" x2="12" y1="5" y2="19"/><line x1="5" x2="19" y1="12" y2="12"/></svg>
          </button>
        </div>

        {categories.map(cat => (
          <div key={cat}>
            <button
              onClick={() => toggleCategory(cat)}
              className="w-full flex items-center justify-between px-3 py-2.5 hover:bg-bg-hover transition-colors"
            >
              <span className="text-xs font-semibold text-text-secondary uppercase tracking-wider">{cat}</span>
              <svg
                width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"
                className={`text-text-muted transition-transform ${expandedCategories[cat] ? 'rotate-180' : ''}`}
              >
                <polyline points="6 9 12 15 18 9" />
              </svg>
            </button>
            {expandedCategories[cat] && (
              <div className="border-b border-border/50">
                {siteConfig.watchlist[cat].map(item => (
                  <button
                    key={item.symbol}
                    onClick={() => setSelectedSymbol(item.symbol)}
                    className={`w-full flex items-center justify-between px-4 py-2 text-xs hover:bg-bg-hover transition-colors ${
                      selectedSymbol === item.symbol ? 'bg-accent/5 border-l-2 border-accent' : ''
                    }`}
                  >
                    <div className="flex items-center gap-2 min-w-0">
                      <span className="font-mono font-semibold text-text-primary">{item.symbol}</span>
                    </div>
                    <div className="flex items-center gap-3 flex-shrink-0">
                      <span className="font-mono text-text-primary">{item.last}</span>
                      <span className={`font-mono font-medium ${item.positive ? 'text-gain' : 'text-loss'} w-16 text-right`}>
                        {item.chgPct}
                      </span>
                    </div>
                  </button>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>

      {/* Main Chart Area */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Toolbar */}
        <div className="border-b border-border bg-bg-secondary px-3 py-2 flex items-center gap-2 overflow-x-auto">
          <div className="flex gap-0.5 mr-3">
            {timeframes.map(tf => (
              <button
                key={tf}
                onClick={() => setTimeframe(tf)}
                className={`px-2.5 py-1 rounded text-xs font-medium transition-colors whitespace-nowrap ${
                  timeframe === tf
                    ? 'bg-accent/15 text-accent border border-accent/20'
                    : 'text-text-secondary hover:text-text-primary hover:bg-bg-hover border border-transparent'
                }`}
              >
                {tf}
              </button>
            ))}
          </div>

          <div className="h-5 w-px bg-border mx-1" />

          <div className="flex gap-1">
            {['Indicators', 'Drawing', 'Chart type'].map(tool => (
              <button key={tool} className="px-2.5 py-1 rounded text-xs text-text-secondary hover:text-text-primary hover:bg-bg-hover transition-colors border border-transparent hover:border-border">
                {tool}
              </button>
            ))}
          </div>

          <div className="ml-auto flex items-center gap-2">
            <button className="p-1.5 text-text-muted hover:text-text-primary hover:bg-bg-hover rounded transition-colors">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/></svg>
            </button>
            <button className="p-1.5 text-text-muted hover:text-text-primary hover:bg-bg-hover rounded transition-colors">
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>
            </button>
          </div>
        </div>

        {/* Chart */}
        <div className="flex-1 bg-bg-primary min-h-0">
          <CandlestickChart timeframe={timeframe} />
        </div>

        {/* Bottom Detail Panels */}
        <div className="border-t border-border bg-bg-secondary overflow-y-auto max-h-80 lg:max-h-96">
          <div className="grid grid-cols-1 lg:grid-cols-3 divide-y lg:divide-y-0 lg:divide-x divide-border">
            {/* Stock Detail */}
            <div className="p-4">
              <div className="flex items-center gap-2 mb-3">
                <span className="font-mono font-bold text-lg text-white">{detail.ticker}</span>
                <span className="text-sm text-text-secondary">{detail.name}</span>
                <span className="text-xs text-text-muted bg-bg-primary px-1.5 py-0.5 rounded">{detail.exchange}</span>
              </div>
              <div className="flex items-baseline gap-3 mb-3">
                <span className="font-mono text-2xl font-bold text-white">{detail.price}</span>
                <span className="text-xs text-text-muted">{detail.currency}</span>
                <span className="font-mono text-sm font-medium text-loss">{detail.change} ({detail.changePct})</span>
              </div>
              <div className="space-y-1.5 text-xs">
                <div className="flex justify-between"><span className="text-text-muted">Volume</span><span className="font-mono text-text-primary">{detail.volume}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Avg Volume (30D)</span><span className="font-mono text-text-primary">{detail.avgVolume}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Market capitalization</span><span className="font-mono text-text-primary">{detail.marketCap}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Next earnings report</span><span className="font-mono text-accent">{detail.nextEarnings}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Pre-market</span><span className="font-mono text-gain">{detail.preMarket}</span></div>
              </div>
              <div className="mt-3 p-2.5 bg-bg-primary rounded border border-border">
                <p className="text-xs text-text-secondary leading-relaxed">{detail.headline}</p>
              </div>
            </div>

            {/* Key Stats */}
            <div className="p-4">
              <h4 className="font-display font-semibold text-sm text-white mb-3">Key Statistics</h4>
              <div className="grid grid-cols-2 gap-x-6 gap-y-1.5 text-xs">
                <div className="flex justify-between"><span className="text-text-muted">Dividend yield TTM</span><span className="font-mono text-text-primary">{fin.dividendYield}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Payout ratio</span><span className="font-mono text-text-primary">{fin.payoutRatio}</span></div>
                <div className="flex justify-between"><span className="text-text-muted">Last dividend</span><span className="font-mono text-text-primary">{fin.lastDividend}</span></div>
