import { useState, useMemo } from 'react'
import { siteConfig } from '../config/site'

type TimeFrame = '1D' | '5D' | '1M' | '3M' | '6M' | 'YTD' | '1Y' | '5Y' | 'All'
type FinTab = 'Annual' | 'Quarterly'

function CandlestickChart({ timeframe }: { timeframe: TimeFrame }) {
  const candles = useMemo(() => {
    const seed = timeframe.charCodeAt(0)
    const count = timeframe === '1D' ? 24 : timeframe === '5D' ? 35 : timeframe === '1M' ? 22 : 40
    const basePrice = 263
    return Array.from({ length: count }, (_, i) => {
      const rand = Math.sin(seed * 100 + i * 7.3) * 0.5 + 0.5
      const trend = i / count * (seed % 2 === 0 ? 3 : -2)
      const open = basePrice + trend + (rand - 0.5) * 8
      const close = open + (Math.sin(seed + i * 3.7) > 0 ? 1 : -1) * (rand * 4 + 0.5)
      const high = Math.max(open, close) + rand * 2
      const low = Math.min(open, close) - rand * 2
      return { open, close, high, low, positive: close >= open }
    })
  }, [timeframe])

  const allPrices = candles.flatMap(c => [c.high, c.low])
  const minP = Math.min(...allPrices) - 2
  const maxP = Math.max(...allPrices) + 2
  const chartW = 800
  const chartH = 400
  const padX = 60
  const padY = 20
  const drawW = chartW - padX * 2
  const drawH = chartH - padY * 2

  const toY = (p: number) => padY + drawH - ((p - minP) / (maxP - minP)) * drawH
  const barW = Math.max(2, (drawW / candles.length) * 0.6)
  const gap = drawW / candles.length

  const gridLines = 5

  return (
    <svg viewBox={`0 0 ${chartW} ${chartH}`} className="w-full h-full" preserveAspectRatio="xMidYMid meet">
      <defs>
        <linearGradient id="bgGrad" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stopColor="#131722" />
          <stop offset="100%" stopColor="#0F0F0F" />
        </linearGradient>
      </defs>
      <rect width={chartW} height={chartH} fill="url(#bgGrad)" rx="0" />

      {Array.from({ length: gridLines + 1 }, (_, i) => {
        const y = padY + (drawH / gridLines) * i
        const price = maxP - ((maxP - minP) / gridLines) * i
        return (
          <g key={i}>
            <line x1={padX} y1={y} x2={chartW - padX} y2={y} stroke="#2a2e39" strokeWidth="0.5" />
            <text x={padX - 8} y={y + 4} textAnchor="end" fill="#787b86" fontSize="10" fontFamily="JetBrains Mono, monospace">
              {price.toFixed(2)}
            </text>
          </g>
        )
      })}

      {candles.map((c, i) => {
        const x = padX + gap * i + gap / 2
        return (
          <g key={i}>
            <line x1={x} y1={toY(c.high)} x2={x} y2={toY(c.low)} stroke={c.positive ? '#26a69a' : '#F7525F'} strokeWidth="1" />
            <rect
              x={x - barW / 2}
              y={toY(Math.max(c.open, c.close))}
              width={barW}
              height={Math.max(1, Math.abs(toY(c.open) - toY(c.close)))}
              fill={c.positive ? '#26a69a' : '#F7525F'}
              rx="0.5"
            />
          </g>
        )
      })}

      <text x={padX} y={padY - 5} fill="#d1d4dc" fontSize="13" fontFamily="Space Grotesk, sans-serif" fontWeight="600">
        AAPL — Apple Inc
      </text>
      <text x={padX} y={padY + 14} fill="#F7525F" fontSize="11" fontFamily="JetBrains Mono, monospace">
        263.40  −3.03 (−1.14%)
      </text>
    </svg>
  )
}

